    """A fixed-capacity least-recently-used cache.

    get(key) returns the stored value or None and marks the key as used.
    put(key, value) inserts or updates and marks the key as used.
    When an insertion would exceed capacity, the least recently used key is
    evicted first.
    """

    def __init__(self, capacity):
        if capacity < 1:
            raise ValueError("capacity must be at least 1")
        self.capacity = capacity
        self._data = {}

    def get(self, key):
        if key not in self._data:
            return None
        value = self._data.pop(key)
        self._data[key] = value
        return value

    def put(self, key, value):
        if key in self._data:
            self._data.pop(key)
        elif len(self._data) >= self.capacity:
            oldest = next(iter(self._data))
            del self._data[oldest]
        self._data[key] = value

    def __len__(self):
        return len(self._data)

    def __contains__(self, key):
        return key in self._data

    def __repr__(self):
        return "LRUCache(capacity=%r, items=%r)" % (self.capacity, list(self._data))
